var inputDone bool

func isInputDone() bool { return inputDone }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		// if contains spaces inside, try trimming and removing spaces
		// fallback 0
		return 0
	}
	return v
}

func parsePriceField(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.New(0, 0)
	}
	// s is 6 digits with implied 2 decimals
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return decimal.New(0, 0)
	}
	return decimal.New(v, -2)
}

// pow10 int64
func pow10(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatEdited(value decimal.Decimal, picture string) string {
	// Find dot
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracSlots++
		}
	}

	// get integer and fractional strings
	// value may be negative - handle absolute and sign not needed for this program (all positive)
	neg := value.IsNegative()
	if neg {
		value = value.Neg()
	}
	// Truncate to fracSlots (value should already have correct scale but ensure)
	// Use Truncate for safety
	value = value.Truncate(int32(fracSlots))

	// Get coefficient
	// Use string representation to extract
	// Convert to integer scaled by fracSlots: value * 10^fracSlots
	scaled := value.Shift(int32(fracSlots)) // multiply by 10^fracSlots
	// scaled should be integer
	// Get integer part and fractional part strings via division
	// scalable as int64 may overflow for large capacities (up to 10 digits => fits in 64)
	// Use decimal's String
	// For edited formatting we need integer part digits
	// Use floor
	intPart := value.Truncate(0) // integer portion
	// But for cases where intSlots may be less than actual digits, we still need low-order truncation
	// Get integer digits via scaled
	// integer digits = floor(value)
	// fractional digits = (scaled - intPart*10^fracSlots)
	tenFrac := decimal.New(1, int32(fracSlots)) // 10^fracSlots
	// intPart decimal
	intPartDec := value.Truncate(0)
	fracPartDec := scaled.Sub(intPartDec.Shift(int32(fracSlots)))
	// Convert to strings
	intStr := intPartDec.Abs().StringFixed(0) // no decimal
	// intStr may be "0"
	fracStr := ""
	if fracSlots > 0 {
		// fracPartDec is integer 0..10^fracSlots-1
		fv := fracPartDec.IntPart() // fits
		fracStr = fmt.Sprintf("%0*d", fracSlots, fv)
	}

	// Build integer digits padded/truncated to intSlots
	var intDigits string
	if len(intStr) > intSlots {
		intDigits = intStr[len(intStr)-intSlots:]
	} else if len(intStr) < intSlots {
		intDigits = strings.Repeat("0", intSlots-len(intStr)) + intStr
	} else {
		intDigits = intStr
	}
	// Handle case intSlots==0
	// Prepare result array
	picRunes := []rune(picture)
	res := make([]rune, len(picRunes))
	for i, c := range picRunes {
		res[i] = c
	}

	// Fill integer Z/9 positions
	intPos := 0 // index into intDigits left to right
	// Build list of indices for integer slots in order
	type slot struct {
		picIdx int
		kind   rune // Z or 9
	}
	var intSlotsIdx []slot
	limit := len(picRunes)
	if dotIdx >= 0 {
		limit = dotIdx
	}
	for i := 0; i < limit; i++ {
		if picRunes[i] == 'Z' || picRunes[i] == '9' {
			intSlotsIdx = append(intSlotsIdx, slot{i, picRunes[i]})
		}
	}
	// Map digits to slots left to right
	for i, sl := range intSlotsIdx {
		ch := intDigits[i]
		res[sl.picIdx] = rune(ch)
		_ = sl.kind
	}

	// Fill fractional slots left to right
	if dotIdx >= 0 {
		var fracSlotsIdx []int
		for i := dotIdx + 1; i < len(picRunes); i++ {
			if picRunes[i] == 'Z' || picRunes[i] == '9' {
				fracSlotsIdx = append(fracSlotsIdx, i)
			}
		}
		for i, idx := range fracSlotsIdx {
			if i < len(fracStr) {
				res[idx] = rune(fracStr[i])
			} else {
				res[idx] = '0'
			}
		}
		// dot stays '.'
	}

	// Apply Z suppression for integer part
	suppress := true
	for i := 0; i < limit; i++ {
		c := picRunes[i]
		switch c {
		case 'Z':
			d := res[i]
			if d != '0' {
				suppress = false
				// keep digit
			} else {
				if suppress {
					res[i] = ' '
				} else {
					res[i] = '0'
				}
			}
		case '9':
			d := res[i]
			if d != '0' {
				suppress = false
			}
			// always keep digit (res already digit)
		case ',':
			if suppress {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		case '.':
		default:
		}
	}
	// Handle sign if needed (not required)
	if neg {
		// COBOL edited sign handling not needed
	}

	// Ensure length equals picture length
	return string(res)
}

func formatPIC99(v int64, width int) string {
	// zero-padded width, low-order digits
	mod := pow10(width)
	// keep low-order digits for positive; handle negative not needed
	mv := v % mod
	if mv < 0 {
		mv += mod
	}
	return fmt.Sprintf("%0*d", width, mv)
}

func truncateToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}
func roundToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

// store into PIC 9(intDigits)V99 etc : keep low-order digits (modulo 10^(intDigits+scale))
func storeDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// d is already truncated/rounded to scale
	// apply modulo 10^(intDigits+scale) in scaled integer domain
	totalDigits := intDigits + int(scale)
	mod := decimal.New(1, int32(totalDigits)) // 10^totalDigits
	// need modulo for positive numbers: scaled = d *10^scale
	scaled := d.Shift(scale) // int
	// For positive, modulo
	// Use DivMod? scaled may be large but within decimal
	// scaled.Mod(mod) for positive
	// decimal.Mod not available directly, compute remainder = scaled - floor(scaled/mod)*mod
	if scaled.IsNegative() {
		// for completeness
		// COBOL store would keep low-order digits preserving sign? Not needed
		q := scaled.Div(mod).Truncate(0)
		rem := scaled.Sub(q.Mul(mod))
		return rem.Shift(-scale)
	}
	q := scaled.Div(mod).Truncate(0) // floor
	rem := scaled.Sub(q.Mul(mod))
	return rem.Shift(-scale)
}

func storizeWsTotal(d decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99
	return storeDecimal(d, 8, 2)
}
func storizeWsGrand(d decimal.Decimal) decimal.Decimal {
	return storeDecimal(d, 10, 2)
}

// file handling
var orderFile *os.File
var scanner *bufio.Scanner
var orderRecords []string
var orderIdx int

func openInput() {
	f, err := os.Open("input.dat")
