	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips newline; keep as is (without newline)
		orderRecords = append(orderRecords, line)
	}
