	f.Close()
	orderIdx = 0
}

func readPara() {
	if orderIdx >= len(orderRecords) {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	raw := orderRecords[orderIdx]
	orderIdx++
	// pad with spaces to 15
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	orderRec.OrId = raw[0:5]
	orderRec.OrStat = raw[5:6]
	orderRec.OrQty = parseIntField(raw[6:9])
	orderRec.OrPrice = parsePriceField(raw[9:15])
	WsEofFlag = "N"
	inputDone = false
}

func showPara() {
	WsQtyEd = formatEdited(decimal.New(orderRec.OrQty, 0), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func processPara() {
	// MOVE 0 TO WS-TOTAL
	WsTotal = decimal.New(0, 0)
	// store to field scale 2
	WsTotal = storizeWsTotal(truncateToScale(WsTotal, 2))

	evaluated := false
	if orderRec.OrQty == 0 {
		// WHEN OR-QTY = 0
		WsBadQty++
		if WsBadQty >= 100 {
			WsBadQty %= 100
		}
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
		evaluated = true
	} else if orderRec.OrStat == "N" {
		// WHEN OR-STAT = "N"
		comp := decimal.New(orderRec.OrQty, 0).Mul(orderRec.OrPrice)
		comp = truncateToScale(comp, 2)
		WsTotal = storizeWsTotal(comp)
		WsNewCount++
		if WsNewCount >= 100 {
			WsNewCount %= 100
		}
		showPara()
		evaluated = true
	} else if orderRec.OrStat == "S" {
		comp := decimal.New(orderRec.OrQty, 0).Mul(orderRec.OrPrice).Mul(decimal.New(105, -2)) // 1.05
		comp = roundToScale(comp, 2)
		WsTotal = storizeWsTotal(comp)
		WsShipCount++
		if WsShipCount >= 100 {
			WsShipCount %= 100
		}
		showPara()
		evaluated = true
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		if WsCancelCount >= 100 {
			WsCancelCount %= 100
		}
		showPara()
		evaluated = true
	} else {
		// WHEN OTHER
		WsInvalid++
		if WsInvalid >= 100 {
			WsInvalid %= 100
		}
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
		evaluated = true
	}
	_ = evaluated

	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = storizeWsGrand(truncateToScale(WsGrand, 2))

	readPara()
}

func summaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	newStr := formatPIC99(WsNewCount, 2)
	shipStr := formatPIC99(WsShipCount, 2)
	cancelStr := formatPIC99(WsCancelCount, 2)
	invalidStr := formatPIC99(WsInvalid, 2)
	badQtyStr := formatPIC99(WsBadQty, 2)
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", newStr, shipStr, cancelStr)
	fmt.Printf("INVALID: %s BAD QTY: %s\n", invalidStr, badQtyStr)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsTotal = decimal.New(0, 0)
	WsGrand = decimal.New(0, 0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0

	openInput()
	readPara()
	for !isInputDone() {
		processPara()
	}
	// CLOSE ORDER-FILE (already closed)
	summaryPara()
}

